#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Edge {
    int to, rev, cap;
    ll cost;
};

struct MinCostFlow {
    int N;
    vector<vector<Edge>> g;
    MinCostFlow(int n) : N(n), g(n) {}

    void addEdge(int s, int t, int cap, ll cost) {
        Edge a{t, (int)g[t].size(), cap, cost};
        Edge b{s, (int)g[s].size(), 0, -cost};
        g[s].push_back(a);
        g[t].push_back(b);
    }

    pair<int, ll> minCostMaxFlow(int s, int t, int maxf) {
        const ll INF = (1LL << 60);
        int flow = 0;
        ll cost = 0;
        vector<ll> dist(N), pot(N, 0);
        vector<int> pv(N), pe(N);

        while (flow < maxf) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
            pq.push({0, s});

            while (!pq.empty()) {
                auto [d, v] = pq.top();
                pq.pop();
                if (d != dist[v]) continue;
                for (int i = 0; i < (int)g[v].size(); i++) {
                    Edge &e = g[v][i];
                    if (e.cap <= 0) continue;
                    ll nd = d + e.cost + pot[v] - pot[e.to];
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;
            for (int v = 0; v < N; v++) {
                if (dist[v] < INF) pot[v] += dist[v];
            }

            int addf = maxf - flow;
            for (int v = t; v != s; v = pv[v]) {
                addf = min(addf, g[pv[v]][pe[v]].cap);
            }

            flow += addf;
            cost += 1LL * addf * pot[t];

            for (int v = t; v != s; v = pv[v]) {
                Edge &e = g[pv[v]][pe[v]];
                e.cap -= addf;
                g[v][e.rev].cap += addf;
            }
        }

        return {flow, cost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

