public class Main {
    static int[] head, to, next, cap;
    static long[] cost;
    static int cnt;
    static int N_nodes;

    static void init(int n, int m) {
        N_nodes = n;
        head = new int[n]; Arrays.fill(head, -1);
        to = new int[m*2]; next = new int[m*2]; cap = new int[m*2]; cost = new long[m*2];
        cnt = 0;
    }

    static void addEdge(int u, int v, int c, long w) {
        to[cnt]=v; cap[cnt]=c; cost[cnt]=w; next[cnt]=head[u]; head[u]=cnt++;
        to[cnt]=u; cap[cnt]=0; cost[cnt]=-w; next[cnt]=head[v]; head[v]=cnt++;
    }

    static long minCostFlow(int s, int t, int maxFlow) {
        long totalCost = 0;
        while (maxFlow > 0) {
            long[] dist = new long[N_nodes]; Arrays.fill(dist, Long.MAX_VALUE/2);
            boolean[] inq = new boolean[N_nodes];
            int[] prevv = new int[N_nodes], preve = new int[N_nodes];
            dist[s] = 0; Queue<Integer> q = new LinkedList<>(); q.add(s); inq[s]=true;
            while (!q.isEmpty()) {
                int v = q.poll(); inq[v]=false;
                for (int e=head[v];e!=-1;e=next[e]) if (cap[e]>0 && dist[v]+cost[e]<dist[to[e]]) {
                    dist[to[e]]=dist[v]+cost[e]; prevv[to[e]]=v; preve[to[e]]=e;
                    if (!inq[to[e]]) { inq[to[e]]=true; q.add(to[e]); }
                }
            }
            if (dist[t] >= 0) break; // no beneficial augmentation
            int d = maxFlow;
            for (int v=t;v!=s;v=prevv[v]) d=Math.min(d,cap[preve[v]]);
            for (int v=t;v!=s;v=prevv[v]) { cap[preve[v]]-=d; cap[preve[v]^1]+=d; }
            totalCost += d * dist[t];
            maxFlow -= d;
        }
        return totalCost;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H=sc.nextInt(), W=sc.nextInt(), N=sc.nextInt();
        int S=H+W, T=H+W+1;
        init(H+W+2, N+H+W+10);
        for (int i=0;i<H;i++) addEdge(S,i,1,0);
        for (int i=0;i<W;i++) addEdge(H+i,T,1,0);
        for (int i=0;i<N;i++) {
            int r=sc.nextInt()-1, c=sc.nextInt()-1; long a=sc.nextLong();
            addEdge(r,H+c,1,-a);
        }
        System.out.println(-minCostFlow(S,T,H));
    }
}

