/*
We need the maximum weight subset of cards such that
- at most one chosen card in each row
- at most one chosen card in each column

This is maximum weight matching in a bipartite graph:
rows <-> columns, each card is an edge with weight A.

Constraints are not shown in the statement here, so we implement a standard
Min-Cost Max-Flow solution for maximum weight bipartite matching.

Construction:
source -> each row (cap 1, cost 0)
row -> column for each card (cap 1, cost -A_i)
each column -> sink (cap 1, cost 0)

Then repeatedly send flow only while the shortest augmenting path has negative
total cost. The answer is - (minimum total cost).

This allows choosing any number of pairs, including zero.

If multiple cards are on the same (row, column), we can keep all edges; MCMF handles it.
*/

public class Main {
    // ---------- Fast Scanner ----------
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    // ---------- Min Cost Flow ----------
    static class Edge {
        int to, rev, cap;
        long cost;
        Edge(int to, int rev, int cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class MinCostFlow {
        int n;
        ArrayList<Edge>[] g;

        @SuppressWarnings("unchecked")
        MinCostFlow(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        }

        void addEdge(int s, int t, int cap, long cost) {
            Edge a = new Edge(t, g[t].size(), cap, cost);
            Edge b = new Edge(s, g[s].size(), 0, -cost);
            g[s].add(a);
            g[t].add(b);
        }

        // Sends augmenting paths while shortest path cost < 0.
        long maxWeightMatchingValue(int s, int t) {
            long[] potential = new long[n];
            long resultCost = 0;

            final long INF = Long.MAX_VALUE / 4;

            while (true) {
                long[] dist = new long[n];
                Arrays.fill(dist, INF);
                dist[s] = 0;

                Edge[] prevEdge = new Edge[n];
                int[] prevNode = new int[n];

                PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
                pq.add(new long[]{0, s});

                while (!pq.isEmpty()) {
                    long[] cur = pq.poll();
                    long d = cur[0];
                    int v = (int) cur[1];
                    if (d != dist[v]) continue;

                    for (Edge e : g[v]) {
                        if (e.cap <= 0) continue;
                        long nd = d + e.cost + potential[v] - potential[e.to];
                        if (nd < dist[e.to]) {
                            dist[e.to] = nd;
                            prevNode[e.to] = v;
                            prevEdge[e.to] = e;
                            pq.add(new long[]{nd, e.to});
                        }
                    }
                }

                if (dist[t] == INF) break;

                for (int i = 0; i < n; i++) {
                    if (dist[i] < INF) potential[i] += dist[i];
                }

                // Real shortest path cost from s to t is potential[t] after update
                long pathCost = potential[t];
                if (pathCost >= 0) break; // no profitable augmentation

                int add = Integer.MAX_VALUE;
                for (int v = t; v != s; v = prevNode[v]) {
                    add = Math.min(add, prevEdge[v].cap);
                }

                for (int v = t; v != s; v = prevNode[v]) {
                    Edge e = prevEdge[v];
                    e.cap -= add;
                    g[v].get(e.rev).cap += add;
                }

                resultCost += pathCost * add;
            }

            return -resultCost;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int H = fs.nextInt();
        int W = fs.nextInt();
        int N = fs.nextInt();

        int S = 0;
        int rowBase = 1;
        int colBase = rowBase + H;
        int T = colBase + W;
        int V = T + 1;

        MinCostFlow mcf = new MinCostFlow(V);

        for (int r = 0; r < H; r++) mcf.addEdge(S, rowBase + r, 1, 0);
        for (int c = 0; c < W; c++) mcf.addEdge(colBase + c, T, 1, 0);

        for (int i = 0; i < N; i++) {
            int r = fs.nextInt() - 1;
            int c = fs.nextInt() - 1;
            long a = fs.nextLong();
            mcf.addEdge(rowBase + r, colBase + c, 1, -a);
        }

        long ans = mcf.maxWeightMatchingValue(S, T);
        System.out.println(ans);
    }
}

