#define MAXN 505
#define NEG_INF (-1000000000LL)

int H, W, N;
long long cost[MAXN][MAXN]; // cost[i][j] = value of card at row i, col j (or NEG_INF)
long long u[MAXN], v[MAXN];
int p[MAXN], way[MAXN];

// Hungarian algorithm for maximum weight matching
// Returns maximum weight matching between rows [1..H] and cols [1..W]
long long hungarian() {
    int n = H > W ? H : W;
    // We want maximum, so we negate and find minimum
    // But missing edges should be 0 (we don't have to pick)
    // Actually we want max sum, missing = 0 contribution

    // Use potential-based Hungarian for max weight
    // Convert to min by negating
    long long a[MAXN][MAXN];
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            a[i][j] = (i <= H && j <= W && cost[i][j] != NEG_INF) ? -cost[i][j] : 0;

    memset(u, 0, sizeof(u));
    memset(v, 0, sizeof(v));
    memset(p, 0, sizeof(p));
    memset(way, 0, sizeof(way));

    for (int i = 1; i <= n; i++) {
        p[0] = i;
        int j0 = 0;
        long long minv[MAXN];
        bool used[MAXN];
        for (int j = 0; j <= n; j++) { minv[j] = 1e18; used[j] = false; }
        do {
            used[j0] = true;
            int i0 = p[j0], j1;
            long long delta = 1e18;
            for (int j = 1; j <= n; j++) {
                if (!used[j]) {
                    long long cur = a[i0][j] - u[i0] - v[j];
                    if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                    if (minv[j] < delta) { delta = minv[j]; j1 = j; }
                }
            }
            for (int j = 0; j <= n; j++) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else minv[j] -= delta;
            }
            j0 = j1;
        } while (p[j0] != 0);
        do { int j1 = way[j0]; p[j0] = p[j1]; j0 = j1; } while (j0);
    }
    long long res = 0;
    for (int j = 1; j <= n; j++)
        if (p[j] != 0 && p[j] <= H && j <= W && cost[p[j]][j] != NEG_INF)
            res += cost[p[j]][j];
    return res;
}

int main() {
    scanf("%d %d %d", &H, &W, &N);
    for (int i = 1; i <= H; i++)
        for (int j = 1; j <= W; j++)
            cost[i][j] = NEG_INF;
    for (int k = 0; k < N; k++) {
        int r, c; long long a;
        scanf("%d %d %lld", &r, &c, &a);
        if (cost[r][c] == NEG_INF || a > cost[r][c])
            cost[r][c] = a;
    }
    printf("%lld\n", hungarian());
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct {
    int to, rev, cap;
    ll cost;
} Edge;

typedef struct {
    Edge *data;
    int size, cap;
} Vec;

static void vec_push(Vec *v, Edge e) {
    if (v->size == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->data = (Edge*)realloc(v->data, sizeof(Edge) * v->cap);
    }
    v->data[v->size++] = e;
}

static void add_edge(Vec *g, int s, int t, int cap, ll cost) {
    Edge a = {t, g[t].size, cap, cost};
    Edge b = {s, g[s].size, 0, -cost};
    vec_push(&g[s], a);
    vec_push(&g[t], b);
}

typedef struct {
    ll dist;
    int v;
} HeapNode;

typedef struct {
    HeapNode *a;
    int size, cap;
} MinHeap;

static void heap_push(MinHeap *h, ll dist, int v) {
    if (h->size == h->cap) {
        h->cap = h->cap ? h->cap * 2 : 16;
        h->a = (HeapNode*)realloc(h->a, sizeof(HeapNode) * h->cap);
    }
    int i = h->size++;
    h->a[i].dist = dist;
    h->a[i].v = v;
    while (i > 0) {
        int p = (i - 1) >> 1;
        if (h->a[p].dist <= h->a[i].dist) break;
        HeapNode tmp = h->a[p];
        h->a[p] = h->a[i];
        h->a[i] = tmp;
        i = p;
    }
}

static HeapNode heap_pop(MinHeap *h) {
    HeapNode res = h->a[0];
    h->size--;
    if (h->size > 0) {
        h->a[0] = h->a[h->size];
        int i = 0;
        while (1) {
            int l = i * 2 + 1, r = i * 2 + 2, m = i;
            if (l < h->size && h->a[l].dist < h->a[m].dist) m = l;
            if (r < h->size && h->a[r].dist < h->a[m].dist) m = r;
            if (m == i) break;
            HeapNode tmp = h->a[i];
            h->a[i] = h->a[m];
            h->a[m] = tmp;
            i = m;
        }
    }
    return res;
}

static int heap_empty(MinHeap *h) {
    return h->size == 0;
}

int main(void) {
    int H, W, N;
    if (scanf("%d %d %d", &H, &W, &N) != 3) return 0;

    /*
      Model as maximum weight bipartite matching:
      - left side: rows
      - right side: columns
      - edge (R_i, C_i) with profit A_i
      Pick at most one per row and column => matching.
      We solve min-cost max-flow with:
        source -> rows (cap 1, cost 0)
        row -> col (cap 1, cost -A_i)
        col -> sink (cap 1, cost 0)
      Send augmenting paths only while total cost decreases (< 0),
      which means total profit increases.
    */

    int S = 0;
    int rowBase = 1;
    int colBase = rowBase + H;
    int T = colBase + W;
    int V = T + 1;

    Vec *g = (Vec*)calloc(V, sizeof(Vec));

    for (int i = 0; i < H; i++) add_edge(g, S, rowBase + i, 1, 0);
    for (int j = 0; j < W; j++) add_edge(g, colBase + j, T, 1, 0);

    for (int i = 0; i < N; i++) {
        int r, c;
        ll a;
        scanf("%d %d %lld", &r, &c, &a);
        --r; --c;
        add_edge(g, rowBase + r, colBase + c, 1, -a);
    }

    const ll INF = (1LL << 60);
    ll *pot = (ll*)calloc(V, sizeof(ll));
    ll *dist = (ll*)malloc(sizeof(ll) * V);
    int *pv = (int*)malloc(sizeof(int) * V);
    int *pe = (int*)malloc(sizeof(int) * V);

    ll answer = 0;

    while (1) {
        for (int i = 0; i < V; i++) {
            dist[i] = INF;
            pv[i] = -1;
            pe[i] = -1;
        }

        MinHeap heap = {0};
        dist[S] = 0;
        heap_push(&heap, 0, S);

        while (!heap_empty(&heap)) {
            HeapNode cur = heap_pop(&heap);
            ll d = cur.dist;
            int v = cur.v;
            if (d != dist[v]) continue;

            for (int i = 0; i < g[v].size; i++) {
                Edge *e = &g[v].data[i];
                if (e->cap <= 0) continue;
                ll nd = d + e->cost + pot[v] - pot[e->to];
                if (nd < dist[e->to]) {
                    dist[e->to] = nd;
                    pv[e->to] = v;
                    pe[e->to] = i;
                    heap_push(&heap, nd, e->to);
                }
            }
        }

        free(heap.a);

        if (dist[T] == INF) break;

        for (int i = 0; i < V; i++) {
            if (dist[i] < INF) pot[i] += dist[i];
        }

        ll pathCost = pot[T] - pot[S];
        if (pathCost >= 0) break;  // no more profitable augmentation

        int add = 1;
        for (int v = T; v != S; v = pv[v]) {
            Edge *e = &g[pv[v]].data[pe[v]];
            if (e->cap < add) add = e->cap;
        }

        for (int v = T; v != S; v = pv[v]) {
            Edge *e = &g[pv[v]].data[pe[v]];
            e->cap -= add;
            g[v].data[e->rev].cap += add;
        }

        answer += -pathCost * add;
    }

    printf("%lld\n", answer);

    for (int i = 0; i < V; i++) free(g[i].data);
    free(g);
    free(pot);
    free(dist);
    free(pv);
    free(pe);

    return 0;
}
